SELECT 
FROM mp_publication

    deleted = 0
    AND category_code = #{category}
    AND product_type = #{productType}
    AND status = #{status}
    AND author_id = #{authorId}

        AND (name LIKE CONCAT('%', #{keyword}, '%')
          OR summary LIKE CONCAT('%', #{keyword}, '%')
          OR code LIKE CONCAT('%', #{keyword}, '%'))


ORDER BY

    avg_rating DESC, rating_count DESC, id DESC
    install_count DESC, id DESC
    published_at DESC, id DESC
    published_at DESC, id DESC

LIMIT #{offset}, #{limit}

SELECT COUNT(*) FROM mp_publication

    deleted = 0
    AND category_code = #{category}
    AND product_type = #{productType}
    AND status = #{status}
    AND author_id = #{authorId}

        AND (name LIKE CONCAT('%', #{keyword}, '%')
          OR summary LIKE CONCAT('%', #{keyword}, '%')
          OR code LIKE CONCAT('%', #{keyword}, '%'))
